// Imported versions (storage.VersionImporter).
//
// An imported version is stored like any other version: a data file written
// through tmp/ and a "ver" record at a fresh (newest) per-bucket sequence.
// Only its identity differs: the version ID, LastModified time and delete
// marker flag are taken from the source. Because an imported ID does not
// embed the sequence (and an ID generated by another fs backend embeds a
// sequence that means nothing here), the "imp" index maps it to the
// sequence; versionPosition consults it before parsing an ID, so every
// lookup by version ID finds imported versions. Imported null versions use
// the "null" index like local ones.

var (
	_ storage.VersionImporter     = (*Backend)(nil)
	_ storage.CompressingImporter = (*Backend)(nil)
)

// importedIdentity is the identity an imported version keeps.
type importedIdentity struct {
	versionID    string
	lastModified time.Time
	deleteMarker bool
}

// importVersion stores rec, whose VersionID, LastModified and DeleteMarker
// are already set, as the newest version of key. An existing version with
// the same ID (for "null": the key's null version) is removed first. It
// maintains the null, imported-ID, data and current indexes and returns
// data IDs to unlink after commit.
func importVersion(bb *bbolt.Bucket, key string, rec *versionRecord) ([]string, error) {
	var unlink []string
	vers := bb.Bucket(subVersions)
	if ovk, ok := versionPosition(bb, key, rec.VersionID); ok {
		if v := vers.Get(ovk); v != nil {
			var orec versionRecord
			if err := decodeRecord(v, &orec); err != nil {
				return nil, err
			}
			if orec.VersionID == rec.VersionID {
				id, err := removeVersion(bb, key, ovk, &orec)
				if err != nil {
					return nil, err
				}
				if id != "" {
					unlink = append(unlink, id)
				}
			}
		}
	}
	seq, err := bb.NextSequence()
	if err != nil {
		return nil, err
	}
	inv := invert(seq)
	if rec.VersionID == storage.NullVersionID {
		if err := bb.Bucket(subNull).Put([]byte(key), invBytes(inv)); err != nil {
			return nil, err
		}
	} else {
		imp, err := bb.CreateBucketIfNotExists(subImported)
		if err != nil {
			return nil, err
		}
		if err := imp.Put(importedKey(key, rec.VersionID), invBytes(inv)); err != nil {
			return nil, err
		}
	}
	vk := versionKey(key, inv)
	if err := putRecord(vers, vk, rec); err != nil {
		return nil, err
	}
	if rec.DataID != "" {
		if err := bb.Bucket(subData).Put([]byte(rec.DataID), vk); err != nil {
			return nil, err
		}
	}
	if err := refreshCurrent(bb, key); err != nil {
		return nil, err
	}
	return unlink, nil
}

// versionWriter is the storage.VersionWriter of the fs backend. Like
// objectWriter it streams to a temporary file and commits through
// commitObject.
type versionWriter struct {
	b        *Backend
	bucket   string
	bucketID string
	key      string

	mu sync.Mutex
	t  *tmpFile
	// cw compresses into t when the version is stored compressed; rw
	// archives restic versions instead of t; w is where written data goes
	// (cw, rw or t).
	cw          *compress.Writer
	rw          *resticWriter
	w           io.Writer
	compression string
	encryption  string
	done        bool
}

// NewVersionWriter starts writing an imported version of bucket/key (see
// storage.VersionImporter). Data is streamed to a temporary file; nothing is
// visible until Commit.
func (b *Backend) NewVersionWriter(ctx context.Context, bucket, key string) (storage.VersionWriter, error) {
	return b.NewVersionWriterWith(ctx, bucket, key, storage.WriteOptions{})
}

// NewVersionWriterWith is NewVersionWriter with write options (see
// storage.CompressingImporter). Restic versions are archived as in
// NewObjectWriterWith.
func (b *Backend) NewVersionWriterWith(ctx context.Context, bucket, key string, opts storage.WriteOptions) (storage.VersionWriter, error) {
	if err := checkCompression(opts.Compression); err != nil {
		return nil, err
	}
	if err := validKey(key); err != nil {
		return nil, err
	}
	id, err := b.encryptionBucketID(ctx, bucket)
	if err != nil {
		return nil, err
	}
	w := &versionWriter{b: b, bucket: bucket, bucketID: id, key: key, encryption: opts.Encryption}
	if opts.Encryption == storage.EncryptionRestic {
		if w.rw, err = b.newResticWriter(ctx, id, bucket, key); err != nil {
			return nil, err
		}
		w.t, w.w = b.newTemp(), w.rw
		return w, nil
	}
	if w.t, err = b.encryptedTemp(id, opts.Encryption); err != nil {
		return nil, err
	}
	w.compression = opts.Compression.Algorithm
	if w.cw, err = newCompressor(w.t, opts.Compression); err != nil {
		return nil, err
	}
	w.w = w.t
	if w.cw != nil {
		w.w = w.cw
	}
	return w, nil
}

// discard drops the written data.
func (w *versionWriter) discard() {
	if w.cw != nil {
		w.cw.Abandon()
	}
	if w.rw != nil {
		w.rw.abort()
	}
	w.t.discard()
}

func (w *versionWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	if w.done {
		return 0, errWriterDone
	}
	return w.w.Write(p)
}

// Commit stores the written data as the newest version of the key with the
// identity given by info (see storage.VersionWriter).
func (w *versionWriter) Commit(ctx context.Context, info storage.ObjectInfo) (storage.ObjectInfo, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	if w.done {
		return storage.ObjectInfo{}, errWriterDone
	}
	w.done = true
	defer w.discard()
	if !storage.ValidImportedVersionID(info.VersionID) {
		return storage.ObjectInfo{}, fmt.Errorf("%w: version ID %.80q", storage.ErrInvalidName, info.VersionID)
	}
	if err := w.b.begin(ctx); err != nil {
		return storage.ObjectInfo{}, err
	}
	var (
		size, stored int64
		compression  string
		dataID, path string
		err          error
	)
	if w.rw != nil {
		size = w.rw.size
		if info.DeleteMarker && size > 0 {
			return storage.ObjectInfo{}, fmt.Errorf("%w: delete marker %s/%.64s with data", storage.ErrInvalidName, w.bucket, w.key)
		}
		dataID, path, err = w.rw.finish(nil)
	} else {
		if size, compression, stored, err = sealData(w.t, w.cw, w.compression); err != nil {
			return storage.ObjectInfo{}, err
		}
		if info.DeleteMarker && size > 0 {
			return storage.ObjectInfo{}, fmt.Errorf("%w: delete marker %s/%.64s with data", storage.ErrInvalidName, w.bucket, w.key)
		}
		dataID, path, err = w.b.finishData(w.t, w.bucketID)
	}
	if err != nil {
		return storage.ObjectInfo{}, err
	}
	if path != "" {
		defer w.b.pending.done(path)
	}
	var meta storage.ObjectMeta
	if !info.DeleteMarker {
		meta = cloneMeta(info.ObjectMeta)
		meta.Encryption = w.encryption
	}
	return w.b.commitObject(commitReq{
		bucket:      w.bucket,
		bucketID:    w.bucketID,
		key:         w.key,
		dataID:      dataID,
		size:        size,
		compression: compression,
		storedSize:  stored,
		meta:        meta,
		imported: &importedIdentity{
			versionID:    info.VersionID,
			lastModified: info.LastModified.UTC(),
			deleteMarker: info.DeleteMarker,
		},
	})
}

func (w *versionWriter) Abort() error {
	w.mu.Lock()
	defer w.mu.Unlock()
	if w.done {
		return nil
	}
	w.done = true
	w.discard()
	return nil
}
